import time

class LFUCache:
    def __init__(self, capacity, ttl_seconds=30):
        self.capacity = capacity
        self.ttl_seconds = ttl_seconds
        self.items = {}
        self.sequence = 0

    def put(self, key, value):
        self.sequence += 1
        now = time.monotonic()
        self.items[key] = {
            'value': value,
            'expires_at': now + self.ttl_seconds,
            'frequency': 1,
            'inserted_at': self.sequence,
        }
        if len(self.items) > self.capacity:
            now = time.monotonic()
            expired = [k for k, item in self.items.items() if item['expires_at'] < now]
            for expired_key in expired:
                del self.items[expired_key]
            if len(self.items) > self.capacity:
                victim = min(
                    self.items,
                    key=lambda k: (self.items[k]['frequency'], self.items[k]['inserted_at']),
                )
                del self.items[victim]

    def get(self, key):
        item = self.items.get(key)
        if item is None:
            return None
        if time.monotonic() > item['expires_at']:
            del self.items[key]
            return None
        item['frequency'] += 1
        return item['value']
